// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    // C's Log was the FIRST contract created by the test contract in setUp (nonce 0);
    // recover its deterministic CREATE address from the test contract's address.
    function computeCreate(address sender) internal pure returns (address) {
        // rlp([sender, 0]) = d6 94 <sender> 80
        bytes memory payload = abi.encodePacked(hex"d694", sender, hex"80");
        return address(uint160(uint256(keccak256(payload))));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        Log lg = Log(computeCreate(address(this)));
        (, string memory data, uint val, ) = lg.History(0);

        // General rule: after any successful Put, the log's last entry records
        // exactly the deposited amount (and is a "Put" entry).
        assertTrue(
            val == amount && keccak256(bytes(data)) == keccak256(bytes("Put"))
        );
    }
}

