pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: any address, any positive amount that cannot overflow
        amount = bound(amount, 1, type(uint256).max - 1);
        vm.assume(actor != address(0));

        // Fresh instance with a reachable Log so the log entry can be read back
        Log lg = new Log();
        C cc = new C(address(lg));

        vm.deal(actor, amount);
        vm.prank(actor);
        cc.Put{value: amount}(0);

        // The last logged entry must carry the deposited amount
        uint256 len = lg.History();
        (, , uint256 loggedVal, ) = lg.History(len - 1);
        assertTrue(loggedVal == amount);
    }
}

